using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
namespace CyberPW.Assistant2{internal sealed class GradientPanel:Panel{public Color StartColor=Color.FromArgb(2,37,43),EndColor=Color.FromArgb(9,73,57);public GradientPanel(){SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.UserPaint,true);}protected override void OnPaintBackground(PaintEventArgs e){using(var b=new LinearGradientBrush(ClientRectangle,StartColor,EndColor,90F))e.Graphics.FillRectangle(b,ClientRectangle);}}}
